-- Read-only verification for the schema applied by 0060b_gcd_dump_import.sql.
select object_name as name, kind, present
from (
  select 'creators.gcd_creator_id', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='creators' and column_name='gcd_creator_id')
  union all select 'gcd_issue_details.barcode', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_issue_details' and column_name='barcode')
  union all select 'gcd_issue_details.isbn', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_issue_details' and column_name='isbn')
  union all select 'gcd_issue_details.notes', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_issue_details' and column_name='notes')
  union all select 'gcd_issue_details.indicia_frequency', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_issue_details' and column_name='indicia_frequency')
  union all select 'gcd_issue_details.indicia_publisher', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_issue_details' and column_name='indicia_publisher')
  union all select 'gcd_issue_details.variant_name', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_issue_details' and column_name='variant_name')
  union all select 'gcd_issue_details.keydate', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_issue_details' and column_name='keydate')
  union all select 'gcd_issue_details.rating', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_issue_details' and column_name='rating')
  union all select 'gcd_stories.job_number', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_stories' and column_name='job_number')
  union all select 'gcd_stories.genre', 'column', exists (select 1 from information_schema.columns where table_schema='public' and table_name='gcd_stories' and column_name='genre')
  union all select 'series_creators', 'table', exists (select 1 from information_schema.tables where table_schema='public' and table_name='series_creators')
  union all select 'issue_reprints', 'table', exists (select 1 from information_schema.tables where table_schema='public' and table_name='issue_reprints')
  union all select 'creators_gcd_creator_id_key', 'constraint', exists (select 1 from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and t.relname='creators' and c.conname='creators_gcd_creator_id_key')
  union all select 'creators_name_key removed', 'constraint_removed', not exists (select 1 from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and t.relname='creators' and c.conname='creators_name_key')
  union all select 'series_creators_pkey', 'constraint', exists (select 1 from pg_constraint where conname='series_creators_pkey')
  union all select 'series_creators_creator_id_fkey', 'constraint', exists (select 1 from pg_constraint where conname='series_creators_creator_id_fkey')
  union all select 'series_creators_role_check', 'constraint', exists (select 1 from pg_constraint where conname='series_creators_role_check')
  union all select 'series_creators_issue_count_check', 'constraint', exists (select 1 from pg_constraint where conname='series_creators_issue_count_check')
  union all select 'issue_reprints_pkey', 'constraint', exists (select 1 from pg_constraint where conname='issue_reprints_pkey')
  union all select 'issue_reprints_origin_issue_id_fkey', 'constraint', exists (select 1 from pg_constraint where conname='issue_reprints_origin_issue_id_fkey')
  union all select 'issue_reprints_target_issue_id_fkey', 'constraint', exists (select 1 from pg_constraint where conname='issue_reprints_target_issue_id_fkey')
  union all select 'creators_name_lower_idx', 'index', exists (select 1 from pg_indexes where schemaname='public' and indexname='creators_name_lower_idx')
  union all select 'creators_name_trgm_idx', 'index', exists (select 1 from pg_indexes where schemaname='public' and indexname='creators_name_trgm_idx')
  union all select 'series_creators_creator_idx', 'index', exists (select 1 from pg_indexes where schemaname='public' and indexname='series_creators_creator_idx')
  union all select 'issue_reprints_target_idx', 'index', exists (select 1 from pg_indexes where schemaname='public' and indexname='issue_reprints_target_idx')
  union all select 'pg_trgm', 'extension', exists (select 1 from pg_extension where extname='pg_trgm')
  union all select 'series_creators RLS', 'security', exists (select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='series_creators' and c.relrowsecurity)
  union all select 'issue_reprints RLS', 'security', exists (select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='issue_reprints' and c.relrowsecurity)
  union all select 'series_creators readable', 'policy', exists (select 1 from pg_policies where schemaname='public' and tablename='series_creators' and policyname='series_creators readable')
  union all select 'issue_reprints readable', 'policy', exists (select 1 from pg_policies where schemaname='public' and tablename='issue_reprints' and policyname='issue_reprints readable')
) checks(object_name, kind, present)
order by kind, name;
